#include <bits/stdc++.h>
using namespace std;

struct Operation {
    int type, v, k;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> parent(N + 1, 1), depth(N + 1, 0);
    vector<vector<int>> children(N + 1);

    for (int v = 2; v <= N; ++v) {
        cin >> parent[v];
        children[parent[v]].push_back(v);
    }

    vector<int> tin(N + 1), tout(N + 1);
    int timer = 0;
    vector<pair<int, int>> st;
    st.push_back({1, 0});
    tin[1] = timer++;

    while (!st.empty()) {
        int u = st.back().first;
        int &i = st.back().second;
        if (i < (int)children[u].size()) {
            int v = children[u][i++];
            depth[v] = depth[u] + 1;
            tin[v] = timer++;
            st.push_back({v, 0});
        } else {
            tout[u] = timer;
            st.pop_back();
        }
    }

    auto isAncestor = [&](int a, int b) {
        return tin[a] <= tin[b] && tout[b] <= tout[a];
    };

    int Q;
    cin >> Q;
    vector<Operation> ops(Q);
    for (int i = 0; i < Q; ++i) {
        cin >> ops[i].type >> ops[i].v;
        if (ops[i].type == 1) cin >> ops[i].k;
        else ops[i].k = 0;
    }

    const int BLOCK = 1200;
    const int LOG = 18;

    vector<int> lastTime(N + 1, 0);
    vector<int> blockTime(N + 1, 0);
    vector<vector<int>> up(LOG, vector<int>(N + 1, 1));
    vector<int> baseParent(N + 1, 1);
    vector<int> best(N + 1, 0);

    for (int L = 0; L < Q; L += BLOCK) {
        int R = min(Q, L + BLOCK);

        best[1] = lastTime[1] ? 1 : 0;
        baseParent[1] = 1;

        for (int v = 2; v <= N; ++v) {
            int a = best[parent[v]];
            if (lastTime[v] > (a ? lastTime[a] : 0)) a = v;
            best[v] = a;

            int ancestor = best[parent[v]];
            baseParent[v] = ancestor ? ancestor : parent[v];
        }

        for (int v = 1; v <= N; ++v) up[0][v] = baseParent[v];
        for (int j = 1; j < LOG; ++j) {
            for (int v = 1; v <= N; ++v) {
                up[j][v] = up[j - 1][up[j - 1][v]];
            }
        }

        vector<int> active;
        auto cmpDepth = [&](int a, int b) {
            if (depth[a] != depth[b]) return depth[a] < depth[b];
            return a < b;
        };

        for (int i = L; i < R; ++i) {
            int v = ops[i].v;

            if (ops[i].type == 2) {
                if (blockTime[v] == 0) {
                    active.insert(lower_bound(active.begin(), active.end(), v, cmpDepth), v);
                }
                blockTime[v] = i + 1;
                lastTime[v] = i + 1;
            } else {
                int k = ops[i].k;
                int maxTime = 0;
                vector<int> records;

                for (int c : active) {
                    if (c != v && isAncestor(c, v) && blockTime[c] > maxTime) {
                        maxTime = blockTime[c];
                        records.push_back(c);
                    }
                }

                int r = (int)records.size();
                if (k <= r) {
                    cout << records[r - k] << '\n';
                } else {
                    int node = (r == 0 ? v : baseParent[records[0]]);
                    int steps = k - r;
                    for (int bit = 0; bit < LOG; ++bit) {
                        if (steps & (1 << bit)) node = up[bit][node];
                    }
                    cout << node << '\n';
                }
            }
        }

        for (int v : active) blockTime[v] = 0;
    }

    return 0;
}
